package com.cpf.starter.webhook;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.HexFormat;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.jdbc.core.JdbcTemplate;public final class CpfWebhookClient {private final HttpClient http;private final JdbcTemplate jdbc;private final byte[] secret;private final Duration timeout;public CpfWebhookClient(HttpClient h,JdbcTemplate j,String s,Duration t){http=h;jdbc=j;secret=s.getBytes(StandardCharsets.UTF_8);timeout=t;}public Result deliver(String id,URI uri,byte[] body,String idempotency,String transactionId){if(id==null||idempotency==null||transactionId==null)throw new IllegalArgumentException("webhook identity required");int inserted=jdbc.update("INSERT INTO cpf_webhook_delivery(delivery_id,idempotency_key,transaction_id,target_uri,delivery_status,attempt_count,created_at,updated_at) VALUES(?,?,?,?, 'PENDING',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",id,idempotency,transactionId,uri.toString());try{String sig=sign(body);var request=HttpRequest.newBuilder(uri).timeout(timeout).header("Content-Type","application/json").header("X-CPF-Delivery-Id",id).header("X-CPF-Idempotency-Key",idempotency).header("X-CPF-Signature","sha256="+sig).POST(HttpRequest.BodyPublishers.ofByteArray(body)).build();var response=http.send(request,HttpResponse.BodyHandlers.discarding());String status=response.statusCode()>=200&&response.statusCode()<300?"DELIVERED":"FAILED";jdbc.update("UPDATE cpf_webhook_delivery SET delivery_status=?,http_status=?,attempt_count=attempt_count+1,updated_at=CURRENT_TIMESTAMP WHERE delivery_id=?",status,response.statusCode(),id);return new Result(status,response.statusCode());}catch(Exception ex){jdbc.update("UPDATE cpf_webhook_delivery SET delivery_status='UNKNOWN_RESULT',attempt_count=attempt_count+1,result_detail=?,updated_at=CURRENT_TIMESTAMP WHERE delivery_id=?",ex.getClass().getSimpleName(),id);throw new UnknownResultException(id,ex);}}private String sign(byte[] body){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret,"HmacSHA256"));return HexFormat.of().formatHex(m.doFinal(body));}catch(Exception ex){throw new IllegalStateException(ex);}}public record Result(String status,int httpStatus){}public static final class UnknownResultException extends RuntimeException{public UnknownResultException(String id,Throwable c){super("Webhook UNKNOWN_RESULT: "+id,c);}}}
